using System;
using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;

namespace LittleLeo.Variables;

[CreateAssetMenu(menuName = "Variables References/BattleAction Reference")]
public class BattleActionReference : ScriptableObject
{
	[Header("Variable")]
	[SerializeField]
	private bool externalSet;

	[NonSerialized]
	[HideIf("externalSet")]
	private BattleAction value;

	public BattleAction Value => value;

	public void SetExternalSet(bool value)
	{
		externalSet = value;
	}

	public void SetValue(BattleAction value)
	{
		if (externalSet)
		{
			Debug.LogFormat("Setting BattleAction Value to {0}", value);
			this.value = value;
		}
		else
		{
			Debug.Log($"Cannot set {base.name} from external source, because bool externalSet is false");
		}
	}
}
